insert into public.biblioteca (tipo, titulo, autor, tribunal, sala, fecha, anio, jurisdiccion, fuero, publicacion, articulos, temas, resultado, sumario, sumario_oficial, url, acceso, verificado_el, origen, clave) values
('fallo', 'Cala, Roberto Rubén y otro c/ Herrera, Luis Salvador s/ daños y perjuicios', null, 'Cámara Nacional de Apelaciones en lo Civil', 'K', '2026-04-30'::date, null, 'Nacional', 'Civil', null, null, array['suma asegurada', 'citación en garantía']::text[], 'a favor', 'Las resoluciones de la SSN sobre límites de cobertura buscan acompañar la inflación para que las sumas cubran los daños; por eso el monto de la póliza se ajusta al que fije la SSN vigente al momento del pago. Argumento base para pedir la actualización frente al tercero.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-cala-roberto-ruben-otro-herrera-luis-salvador-danos-perjuicios-fa26020153-2026-04-30/123456789-351-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', 'fbfa166d5b27160962183abe7d5bbdba'),
('fallo', 'Larrosa, Mariel c/ Sueldo, Julieta Lorena y otro s/ daños y perjuicios (acc. tran. c/ les. o muerte)', null, 'Cámara Nacional de Apelaciones en lo Civil', 'J', '2026-03-31'::date, null, 'Nacional', 'Civil', null, null, array['suma asegurada', 'citación en garantía']::text[], 'a favor', 'El límite de cobertura que puede oponer la aseguradora se determina según la normativa de la SSN vigente al momento del efectivo pago de la condena. Criterio breve y directo para citar en la demanda o en la liquidación.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-larrosa-mariel-sueldo-julieta-lorena-otro-danos-perjuicios-acc-tran-les-muerte-fa26020134-2026-03-31/123456789-431-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '8308abaf4d65f65da2dbe5ad042f69cc'),
('fallo', 'Ontiveros, Damián Emiliano y otro c/ Huachuhuillca Ñahuen, Víctor y otro s/ daños y perjuicios (acc. tran. c/ les. o muerte)', null, 'Juzgado Nacional de Primera Instancia en lo Civil N° 34', null, '2026-03-27'::date, null, 'Nacional', 'Civil', null, null, array['suma asegurada', 'citación en garantía']::text[], 'a favor', 'Si la condena se fija a valores actuales, el límite de cobertura también debe llevarse a los parámetros vigentes al pago, para no comparar un tope histórico con una deuda actualizada. Útil cuando la aseguradora pretende aplicar el límite nominal de la póliza.', false, 'https://www.saij.gob.ar/juzgado-nacional-civil-nro-34-nacional-ciudad-autonoma-buenos-aires-ontiveros-damian-emiliano-otro-huachuhuillca-nahuen-victor-otro-danos-perjuicios-acc-tran-les-muerte-fa26020126-2026-03-27/123456789-621-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', 'dce4e368c5e4f4467d7a1ee8a6f33191'),
('fallo', 'García Guerreño, Verónica Beatriz c/ CPC SA Contreras Hermanos SAICIFAG y M UTE s/ daños y perjuicios (acc. tran. c/ les. o muerte)', null, 'Cámara Nacional de Apelaciones en lo Civil', 'E', '2026-03-20'::date, null, 'Nacional', 'Civil', null, null, array['suma asegurada', 'citación en garantía']::text[], 'a favor', 'En el seguro voluntario de responsabilidad civil, el límite pactado se adecua a la realidad económica al momento del pago cuando la inflación desnaturaliza el contrato y enriquece a la aseguradora; como parámetro toma la variación de los límites de la SSN. Sirve cuando la póliza no es la del seguro obligatorio.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-garcia-guerreno-veronica-beatriz-cpc-sa-contreras-hermanos-saicifag-ute-danos-perjuicios-acc-tran-les-muerte-fa26020100-2026-03-20/123456789-001-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '72ffb468059d162936e3df7a614e388e'),
('fallo', 'Díaz Paniagua, Ladislaa c/ Los Constituyentes S.A.T. y otro s/ daños y perjuicios (acc. tran. c/ les. o muerte)', null, 'Cámara Nacional de Apelaciones en lo Civil', 'J', '2026-03-05'::date, null, 'Nacional', 'Civil', null, null, array['suma asegurada', 'citación en garantía', 'franquicia']::text[], 'a favor', 'El límite de cobertura es oponible a la víctima, pero se actualiza a las normas de la SSN vigentes al pago, y la aseguradora en mora carga con capital, intereses y costas. Combina la doctrina de la CSJN sobre oponibilidad con la actualización del tope. Además, declara inoponible a la víctima la franquicia del seguro de un colectivo, por aplicación del plenario vigente en la Cámara Civil.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-diaz-paniagua-ladislaa-constituyentes-sat-otro-danos-perjuicios-acc-tran-les-muerte-fa26020099-2026-03-05/123456789-990-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', 'a814cbdfe1107e2dde86e4354bb9273d'),
('fallo', 'Solonja, Jorge c/ Baido, Néstor Omar y otro s/ daños y perjuicios (acc. tran. c/ les. o muerte)', null, 'Cámara Nacional de Apelaciones en lo Civil', 'H', '2026-02-02'::date, null, 'Nacional', 'Civil', null, null, array['suma asegurada', 'citación en garantía', 'intereses']::text[], 'a favor', 'El límite de cobertura se aplica solo al capital de condena: las costas, los gastos de defensa y los intereses de ese capital quedan a cargo del asegurador aunque superen el tope, por el principio de indemnidad. Clave al liquidar contra la aseguradora.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-solonja-jorge-baido-nestor-omar-otro-danos-perjuicios-acc-tran-les-muerte-fa26020042-2026-02-02/123456789-240-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', 'ee26f40042c2647790fe331995e84cc4'),
('fallo', 'Vidal, Santiago Isaías y otro c/ Osorio, Pablo Daniel s/ daños y perjuicios', null, 'Cámara Nacional de Apelaciones en lo Civil', 'A', '2025-05-14'::date, null, 'Nacional', 'Civil', null, null, array['suma asegurada', 'citación en garantía']::text[], 'a favor', 'Parte de que el límite es oponible y de que la deuda del asegurador es dineraria, pero declara inconstitucional el art. 7 de la Ley 23.928 para el caso y amplía el tope, porque la inflación desde el hecho licuó la cobertura. Vía para pedir la actualización cuando no hay resolución de la SSN aplicable.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-vidal-santiago-isaias-otro-osorio-pablo-daniel-danos-perjuicios-fa25020693-2025-05-14/123456789-396-0205-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', 'f412b24eab2042c59b301b2aba572780'),
('fallo', 'Silva, Tamara Yanil c/ Lago, Santiago Martín y otros s/ daños y perjuicios', null, 'Cámara Nacional de Apelaciones en lo Civil', 'H', '2026-06-05'::date, null, 'Nacional', 'Civil', null, null, array['suma asegurada', 'citación en garantía']::text[], 'a favor', 'El límite de cobertura es inoponible a la víctima cuando asegurado y aseguradora, con intereses contrapuestos, tienen el mismo abogado: esa unificación indebida solo beneficia a la compañía. Conviene revisar quién patrocina a cada demandado.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-silva-tamara-yanil-lago-santiago-martin-otros-danos-perjuicios-fa26020283-2026-06-05/123456789-382-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '56d2c8694077a8d73be45497842e419d'),
('fallo', 'González, Maximiliano Ramiro c/ Acosta, Emir Dorval y otro s/ Daños y perjuicios', null, 'Suprema Corte de Justicia de la Provincia de Buenos Aires', null, '2021-05-28'::date, null, 'PBA', 'Civil y Comercial', null, null, array['suma asegurada', 'citación en garantía']::text[], 'a favor', 'C. 122.588. Oponer literalmente el límite de cobertura al asegurado y a la víctima viola la reparación integral y las resoluciones de la SSN cuando desnaturaliza el contrato, genera infraseguro y beneficia indebidamente a la aseguradora. Doctrina de la SCBA para PBA.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=180714', null, '2026-10-07'::date, 'relevamiento', 'b04ef27d6bce23a1ba697cb0530564bf'),
('fallo', 'Arguello, Gustavo Sergio c/ Cooperación Mutual Patronal Seguros y otros s/ Daños y Perj. Autom. s/ Lesiones (Exc. Estado)', null, 'Cámara Segunda de Apelación en lo Civil y Comercial de La Plata', 'I', '2026-09-01'::date, null, 'PBA', 'Civil y Comercial', null, null, array['suma asegurada', 'citación en garantía']::text[], 'a favor', 'Con la reparación a valores actuales y una aseguradora que rechazó el siniestro y demoró más de cinco años, no se puede limitar la condena a la suma asegurada nominal de 2020: eso premiaría la mora y desnaturalizaría el contrato. Sigue a la SCBA en "Martínez c/ Boito" (C. 119.088).', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=198483', null, '2026-10-07'::date, 'relevamiento', 'b48915ee61a24bde6ef32a5fb796fa65'),
('fallo', 'Azcune, Agustín Patricio y otros c/ Malanchuk, Nelson Daniel s/ Daños y Perj. Autom. c/ Les. o Muerte (Exc. Estado)', null, 'Cámara de Apelación en lo Civil y Comercial de Junín', null, '2024-05-14'::date, null, 'PBA', 'Civil y Comercial', null, null, array['suma asegurada', 'citación en garantía']::text[], 'a favor', 'Condena a la aseguradora a calcular la cobertura básica al momento de la evaluación judicial del daño, en consonancia con los montos de la sentencia y no según la cifra nominal de la póliza, lo que vuelve inoponible el límite histórico al asegurado y a la víctima.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=192091', null, '2026-10-07'::date, 'relevamiento', '5a95381107e4a2a38ec464b265566020'),
('fallo', 'Bartoli, Cecilia Beatriz c/ La Nueva Cooperativa de Seguros Limitada y otro s/ daños y perjuicios', null, 'Cámara de Apelación en lo Civil y Comercial de Mar del Plata', 'II', '2021-12-01'::date, null, 'PBA', 'Civil y Comercial', null, null, array['suma asegurada', 'citación en garantía']::text[], 'a favor', 'Siguiendo a la SCBA en "Martínez c/ Boito" (C. 119.088, 21/2/2018), aplica el límite que fije la SSN para el tipo de seguro (obligatorio o voluntario) vigente a la fecha del pago, comprensivo de capital e intereses. Precedente claro para liquidar en PBA.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=182908', null, '2026-10-07'::date, 'relevamiento', '6b496dbb050b84ee5a0f553772674c46'),
('fallo', 'Cruz, María Elizabeth c/ Marilú Hipólito S. y otros s/ Daños y Perj.', null, 'Cámara de Apelación en lo Civil y Comercial de Azul', 'II', '2019-03-27'::date, null, 'PBA', 'Civil y Comercial', null, null, array['suma asegurada', 'citación en garantía']::text[], 'a favor', 'Como los daños por muerte se fijan a valores actuales, aplica la resolución de la SSN que elevó el límite por muerte o incapacidad total y condena a la aseguradora por la cobertura básica vigente, no por la pactada originalmente. Ejemplo concreto de aplicación de una resolución posterior al hecho.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=168733', null, '2026-10-07'::date, 'relevamiento', '511a8aa8cb88acbc32a788ee21f53092'),
('fallo', 'Centenari Valentino, Gastón José c/ La Nueva Cooperativa de Seguros SA s/ ordinario', null, 'Cámara Nacional de Apelaciones en lo Comercial', 'E', '2025-06-06'::date, null, 'Nacional', 'Comercial', null, null, array['suma asegurada']::text[], 'a favor', 'Reclamo del asegurado contra su propia compañía: por la mora, la suma asegurada histórica pierde virtualidad y se toma el valor con que la aseguradora asegura hoy un vehículo igual con la misma antigüedad. Útil cuando el cliente reclama la destrucción total a su seguro.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-comercial-nacional-ciudad-autonoma-buenos-aires-centenari-valentino-gaston-jose-nueva-cooperativa-seguros-sa-ordinario-fa25131114-2025-06-06/123456789-411-1315-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', 'b20e0f6b863399467a9f53fdd02fc242'),
('fallo', 'Aldinio, Santiago Manuel c/ TPC Compañía de Seguros SA s/ ordinario', null, 'Cámara Nacional de Apelaciones en lo Comercial', 'C', '2025-04-21'::date, null, 'Nacional', 'Comercial', null, null, array['suma asegurada']::text[], 'a favor', 'Mismo criterio para una moto: con la aseguradora en mora no se aplica la suma asegurada histórica sino la que la compañía usa hoy para asegurar una moto igual con la misma antigüedad. Refuerza el criterio en otra sala del fuero comercial.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-comercial-nacional-ciudad-autonoma-buenos-aires-aldinio-santiago-manuel-tpc-compania-seguros-sa-ordinario-fa25130820-2025-04-21/123456789-028-0315-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '3c263692e3e021947a20b831b3fdb9d0'),
('fallo', 'Bernst, Tomás Ariel c/ Escudo Seguros SA s/ ordinario', null, 'Cámara Nacional de Apelaciones en lo Comercial', 'D', '2023-08-10'::date, null, 'Nacional', 'Comercial', null, null, array['suma asegurada']::text[], 'en contra', 'Rechaza dejar de lado el límite de cobertura por la mora de la aseguradora: la mora solo revela el incumplimiento, y la obligación del asegurador nace del contrato, no del daño, por lo que su tope no es la medida del perjuicio. Postura contraria a anticipar.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-comercial-nacional-ciudad-autonoma-buenos-aires-bernst-tomas-ariel-escudo-seguros-sa-ordinario-fa23130880-2023-08-10/123456789-088-0313-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '27b30437a8e66eb90e315eca7a48da80'),
('fallo', 'Pereira Finazzi, Carlos Clodomiro Juan c/ Latitude SRL s/ ordinario', null, 'Cámara Nacional de Apelaciones en lo Comercial', 'A', '2026-02-26'::date, null, 'Nacional', 'Comercial', null, null, array['desvalorización']::text[], 'a favor', 'Admite la desvalorización de un auto chocado por un empleado de una playa de estacionamiento. Como el modelo estaba discontinuado, manda que el perito informe el precio actual de un vehículo similar y fija el rubro como un porcentaje de ese valor. Sirve como pauta de cuantificación.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-comercial-nacional-ciudad-autonoma-buenos-aires-pereira-finazzi-carlos-clodomiro-juan-latitude-srl-ordinario-fa26130116-2026-02-26/123456789-611-0316-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '556d7bdbf9d54e964f4acc4aaba285fe'),
('fallo', 'Burgos, Carlos Martín c/ Caja de Seguros SA y otro s/ ordinario', null, 'Cámara Nacional de Apelaciones en lo Comercial', 'E', '2024-04-25'::date, null, 'Nacional', 'Comercial', null, null, array['desvalorización']::text[], 'a favor', 'Rechaza que la aseguradora esté eximida de cubrir la desvalorización del vehículo: es daño patrimonial comprendido en el art. 61 de la Ley de Seguros. La prueba de la pérdida de valor queda a cargo del asegurado. Útil en reclamos contra la propia compañía.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-comercial-nacional-ciudad-autonoma-buenos-aires-burgos-carlos-martin-caja-seguros-sa-otro-ordinario-fa24130439-2024-04-25/123456789-934-0314-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '0023ed0cdf9207eb23b21937fa13920d'),
('fallo', 'Ramírez, Sara del Valle c/ Ford Argentina SCA s/ ordinario', null, 'Cámara Nacional de Apelaciones en lo Comercial', 'C', '2024-04-16'::date, null, 'Nacional', 'Comercial', null, null, array['desvalorización']::text[], 'a favor', 'Concede la pérdida de valor venal porque el cambio de motor de una unidad con 8.000 km afecta sus condiciones originales y queda registrado en el legajo. Caso de consumo, pero aporta el criterio de que el reemplazo de piezas fundamentales deprecia el vehículo.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-comercial-nacional-ciudad-autonoma-buenos-aires-ramirez-sara-valle-ford-argentina-sca-ordinario-fa24130296-2024-04-16/123456789-692-0314-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', 'ea07df598fffc9515e4c1a3c06259f83'),
('fallo', 'Riestra, Sergio y otro c/ FCA Importadora SRL s/ ordinario', null, 'Cámara Nacional de Apelaciones en lo Comercial', 'B', '2020-06-16'::date, null, 'Nacional', 'Comercial', null, null, array['desvalorización']::text[], 'a favor', 'Aun cuando las reparaciones dejen el rodado en óptimas condiciones, un experto las advierte y eso, en el mercado de reventa, implica pérdida de valor venal. Argumento directo contra la exigencia de secuelas estructurales.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-comercial-nacional-ciudad-autonoma-buenos-aires-riestra-sergio-otro-fca-importadora-srl-ordinario-fa20137298-2020-06-16/123456789-892-7310-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', 'ee610683e639004db985ea88e54db92d'),
('fallo', 'Ogando, Alberto Ricardo y otra c/ Peugeot Citroen Argentina SA y otra s/ Daños y Perjuicios', null, 'Cámara Segunda de Apelación en lo Civil y Comercial de La Plata', 'II', '2017-04-11'::date, null, 'PBA', 'Civil y Comercial', null, null, array['desvalorización']::text[], 'a favor', 'Que el automotor haya sido reparado satisfactoriamente no impide reconocer la desvalorización: sigue siendo un vehículo que fue arreglado y eso incide en su valor. Precedente de PBA contra el rechazo automático del rubro tras una buena reparación.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=142453', null, '2026-10-07'::date, 'relevamiento', 'a590866c6ceba4768c0e4c562ffd6d4b'),
('fallo', 'Vera, Juan Carlos contra Provincia de Buenos Aires. Daños y perjuicios', null, 'Suprema Corte de Justicia de la Provincia de Buenos Aires', null, '2018-04-18'::date, null, 'PBA', 'Civil y Comercial', null, null, array['intereses']::text[], 'mixto', 'C. 120.536. Precedente de la SCBA: cuando el capital se fija a valores actuales, los intereses desde la mora hasta la cuantificación se calculan a una tasa pura del 6% anual y, desde allí, a la tasa bancaria que fije la doctrina de la Corte. Admite valores actuales, pero baja la tasa del tramo anterior.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=160546', null, '2026-10-07'::date, 'relevamiento', '23c8ec64a468a5fe195bdb117ac9e6a3'),
('fallo', 'Nidera S.A. contra Provincia de Buenos Aires. Daños y perjuicios', null, 'Suprema Corte de Justicia de la Provincia de Buenos Aires', null, '2018-05-03'::date, null, 'PBA', 'Civil y Comercial', null, null, array['intereses']::text[], 'mixto', 'C. 121.134. Reitera a pocas semanas de "Vera" la doctrina de la tasa pura del 6% para créditos estimados a valores actuales, hasta el momento de la evaluación de la deuda. Los fallos posteriores lo citan junto con "Vera" como base de esa doctrina.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=160606', null, '2026-10-07'::date, 'relevamiento', 'ea78e096bedc5db66bce6a25a6517b5b'),
('fallo', 'Barrios, Héctor Francisco y otra contra Lascano, Sandra Beatriz y otra. Daños y perjuicios', null, 'Suprema Corte de Justicia de la Provincia de Buenos Aires', null, '2024-04-17'::date, null, 'PBA', 'Civil y Comercial', null, null, array['intereses']::text[], 'mixto', 'C. 124.096. Revisa la doctrina de la tasa pasiva única ("Cabrera") y fija como pauta que la tasa no puede licuar ni sobreestimar el crédito; mantiene la tasa pura para montos a valores actuales. Las cámaras de PBA la aplican hoy junto con la reglamentación del BCRA (art. 768 inc. c CCyC). JUBA no publica sumarios propios de este fallo.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=197992', null, '2026-10-07'::date, 'relevamiento', '20168600dad2229cb87407680229d80b'),
('fallo', 'Martínez, Emir contra Boito, Alfredo Alberto. Daños y perjuicios', null, 'Suprema Corte de Justicia de la Provincia de Buenos Aires', null, '2018-02-21'::date, null, 'PBA', 'Civil y Comercial', null, null, array['suma asegurada', 'citación en garantía']::text[], 'a favor', 'C. 119.088 (por mayoría). El seguro obligatorio protege a las víctimas con fundamento de orden público; aplicar literalmente el tope de la póliza puede frustrar su finalidad. Por eso admite una revisión equitativa e incluye en la medida del seguro la garantía mínima vigente al valuarse el daño. Doctrina de la SCBA sobre actualización del límite.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=159525', null, '2026-10-07'::date, 'relevamiento', 'e0423d2b43aa994eccfcf2415bc9ad9c'),
('fallo', 'Gomez, María Magdalena y otro/a c/ Legidos, Jonatan Federico s/ Daños y Perj. Autom. c/ Les. o Muerte (Exc. Estado)', null, 'Cámara Segunda de Apelación en lo Civil y Comercial de La Plata', 'III', '2019-07-02'::date, null, 'PBA', 'Civil y Comercial', null, null, array['prescripción', 'mediación']::text[], 'a favor', 'Rechaza la prescripción porque la mediación obligatoria se pidió el día siguiente al vencimiento, dentro del plazo de gracia del art. 124 CPCC, y eso suspendió el plazo por un año. Útil cuando se inicia la mediación al límite.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=172931', null, '2026-10-07'::date, 'relevamiento', 'bbc43e526fd9ed684319bd78c490a400'),
('fallo', 'Céspedes, Zulma Beatriz c/ Sidi, Silvia Patricia y otros s/ Daños y Perjuicios Autom. s/ Lesiones (Exc. Estado)', null, 'Cámara de Apelación en lo Civil y Comercial de San Martín', 'II', '2022-10-18'::date, null, 'PBA', 'Civil y Comercial', null, null, array['prescripción', 'mediación']::text[], 'mixto', 'Interlocutoria. Repasa el régimen de suspensión de la prescripción por mediación: art. 18 de la Ley 26.589 (hasta 20 días después del acta de cierre), plazo para iniciar el juicio y art. 2542 CCyC. Guía para calcular el plazo en accidentes anteriores y posteriores al CCyC.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=194850', null, '2026-10-07'::date, 'relevamiento', '0138f51eb0952242827c6469c0370489'),
('fallo', 'Doval, Romina Gisela c/ La Nueva Metropol S.A.T.A.C.I. s/ daños y perjuicios (acc. tran. c/ les. o muerte)', null, 'Cámara Nacional de Apelaciones en lo Civil', 'H', '2025-04-08'::date, null, 'Nacional', 'Civil', null, null, array['prescripción']::text[], 'mixto', 'Recuerda que el plenario "Sáez González" aplicaba al pasajero transportado el plazo de tres años del art. 50 de la LDC, pero que desde la reforma de la Ley 26.994 ese artículo ya no fija plazo para las acciones judiciales, que pasan a regirse por las normas generales del CCyC. Clave para reclamos de pasajeros de colectivos.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-doval-romina-gisela-nueva-metropol-sataci-danos-perjuicios-acc-tran-les-muerte-fa25020072-2025-04-08/123456789-270-0205-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '48b8175dd237b12d6c21e54d96ad088c'),
('fallo', 'Provincia Aseguradora de Riesgos del Trabajo S.A. c/ Civil resp hecho ocurrido el 28/08/2023 s/ interrupción de prescripción', null, 'Cámara Nacional de Apelaciones en lo Civil', 'de turno (feria)', '2026-07-27'::date, null, 'Nacional', 'Civil', null, null, array['prescripción']::text[], 'a favor', 'Habilita la feria judicial en forma excepcional cuando el receso puede frustrar un derecho por el vencimiento inminente de la prescripción, limitada al efecto de interrumpirla. Útil para demandas que vencen en enero o julio.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-provincia-aseguradora-riesgos-trabajo-sa-civil-resp-hecho-ocurrido-28-08-2023-interrupcion-prescripcion-fa26020420-2026-07-27/123456789-024-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '0222c2b6ab4c921a1de6badeff79050b'),
('fallo', 'A., M. E. c/ F. A. S.C.A. y otros s/ cumplimiento de contrato', null, 'Cámara Nacional de Apelaciones en lo Civil', 'G', '2025-03-19'::date, null, 'Nacional', 'Civil', null, null, array['prescripción', 'mediación']::text[], 'a favor', 'Ratifica que la mediación prejudicial obligatoria es causal de suspensión de la prescripción liberatoria (art. 2542 CCyC y art. 18 de la Ley 26.589). Caso contractual, pero el criterio es general.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires--sca-otros-cumplimiento-contrato-fa25020238-2025-03-19/123456789-832-0205-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '00af1da23df023c6633ff1db09585cd4'),
('fallo', 'Riep, Rodrigo Sebastián c/ Seguros Sura SA s/ ordinario', null, 'Cámara Nacional de Apelaciones en lo Comercial', 'D', '2022-02-22'::date, null, 'Nacional', 'Comercial', null, null, array['prescripción', 'mediación']::text[], 'en contra', 'Si la caducidad de la instancia borra la interrupción de la prescripción por la demanda, con más razón la caducidad de la instancia de mediación borra la suspensión. Advierte que hay que iniciar el juicio dentro del plazo posterior al cierre de la mediación.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-comercial-nacional-ciudad-autonoma-buenos-aires-riep-rodrigo-sebastian-seguros-sura-sa-ordinario-fa22130304-2022-02-22/123456789-403-0312-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', 'fccb26413340221dd828c803286fc479'),
('fallo', 'Arostegui, Pablo Martín c/ Omega Aseguradora de Riesgos del Trabajo S.A. y Pametal Peluso y Compañía S.R.L. y otro s/ inconst. art. 39 LRT', null, 'Corte Suprema de Justicia de la Nación', null, '2008-04-08'::date, null, 'CSJN', 'Laboral', null, null, array['incapacidad']::text[], 'a favor', 'Fallos 331:570. Deja sin efecto por arbitraria la sentencia que cuantificó con "valores constantes" de rentas sin explicarlos, y afirma que la vida e integridad no se miden solo con criterios materiales: la incapacidad se repara también en la vida de relación. Caso laboral, aplicable por analogía al cuestionar fórmulas puramente rentísticas.', false, 'https://sjconsulta.csjn.gov.ar/sjconsulta/documentos/verDocumentoByIdLinksJSP.html?idDocumento=6414601', null, '2026-10-07'::date, 'relevamiento', 'af0b58e34bf98ca26e00d36aa930ab41'),
('fallo', 'Ontiveros, Stella Maris c/ Prevención ART S.A. y otros s/ accidente - inc. y cas.', null, 'Corte Suprema de Justicia de la Nación', null, '2017-08-10'::date, null, 'CSJN', 'Laboral', null, null, array['incapacidad', 'daño moral']::text[], 'a favor', 'Fallos 340:1038. La reparación integral y el derecho a la integridad física tienen jerarquía constitucional y convencional; el resarcimiento no se logra si los valores fijados por el juez resultan insignificantes frente al daño. Base constitucional para pedir montos adecuados.', false, 'https://sjconsulta.csjn.gov.ar/sjconsulta/documentos/verDocumentoByIdLinksJSP.html?idDocumento=7391642', null, '2026-10-07'::date, 'relevamiento', '1adbe71c4f53e70f378d01673405d4c5'),
('fallo', 'Berterreche, Mauro Matías y otros c/ Empresa Línea San Martín Tren Operadora Ferroviaria S.E. y otros s/ daños y perjuicios', null, 'Cámara Nacional de Apelaciones en lo Civil', 'M', '2026-02-23'::date, null, 'Nacional', 'Civil', null, null, array['franquicia']::text[], 'a favor', 'La franquicia alta del seguro de un servicio ferroviario es inoponible a las víctimas cuando es desproporcionada y ninguna norma la impone, porque las deja sin cobertura efectiva y desvirtúa el seguro. Amplía la línea de inoponibilidad a otros transportes públicos.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-berterreche-mauro-matias-otros-empresa-linea-san-martin-tren-operadora-ferroviaria-se-otros-danos-perjuicios-fa26020078-2026-02-23/123456789-870-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '2d8e7a86e6c0a1d1cd8532c3005660fa'),
('fallo', 'Obarrio, María Pía c/ Microómnibus Norte S.A. y otros s/ daños y perjuicios', null, 'Corte Suprema de Justicia de la Nación', null, '2008-03-04'::date, null, 'CSJN', 'Civil', null, null, array['franquicia', 'citación en garantía']::text[], 'en contra', 'La CSJN revocó la sentencia dictada con base en el plenario "Obarrio" de la Cámara Civil, que declaraba inoponible la franquicia del transporte público a la víctima. Es el antecedente que la Corte reitera desde entonces ("Díaz c/ Evangelista", "Sulca"). La base no publica sumarios propios.', false, 'https://sjconsulta.csjn.gov.ar/sjconsulta/documentos/verDocumentoByIdLinksJSP.html?idDocumento=6400111', null, '2026-10-07'::date, 'relevamiento', '9dc422527aa5a36a7abbfb8b43721f50'),
('fallo', 'Gauna, Agustín y su acumulado c/ La Economía Comercial SA de Seguros Generales y otro s/ daños y perjuicios', null, 'Corte Suprema de Justicia de la Nación', null, '2008-03-04'::date, null, 'CSJN', 'Civil', null, null, array['franquicia', 'citación en garantía']::text[], 'en contra', 'Dictado el mismo día que "Obarrio" y con el mismo resultado (revoca). La Corte lo cita junto con "Obarrio" como fuente de la oponibilidad de la franquicia al tercero ("Díaz c/ Evangelista", "Sulca"). La base no publica sumarios propios.', false, 'https://sjconsulta.csjn.gov.ar/sjconsulta/documentos/verDocumentoByIdLinksJSP.html?idDocumento=6402521', null, '2026-10-07'::date, 'relevamiento', '7196aec59fcd9b160b2688c95f59b024'),
('fallo', 'Orellana, Roberto Gastón c/ Portuguez, Dionisio Martín y otro s/ daños y perjuicios', null, 'Cámara Nacional de Apelaciones en lo Civil', 'G', '2026-05-21'::date, null, 'Nacional', 'Civil', null, null, array['daño emergente']::text[], 'a favor', 'La mera disconformidad con el monto de los daños al vehículo no alcanza para reducirlo si la demandada no aporta prueba contra el presupuesto reconocido ni demuestra un costo menor. Respalda reclamar la reparación según presupuesto.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-orellana-roberto-gaston-portuguez-dionisio-martin-otro-danos-perjuicios-fa26020186-2026-05-21/123456789-681-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '698e7257b40c53cff08cd1492d5c2b5c'),
('fallo', 'Sapia, Martín Francisco y otro c/ Peugeot Citroen Argentina SA y otro s/ ordinario', null, 'Cámara Nacional de Apelaciones en lo Comercial', null, '2026-03-17'::date, null, 'Nacional', 'Comercial', null, null, array['daño emergente']::text[], 'a favor', 'Condena a la fabricante que no entregó el repuesto necesario para reparar un vehículo siniestrado a resarcir los gastos y la demora (art. 12 LDC). Útil cuando la reparación se demora por falta de repuestos. La fuente no informa la sala.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-comercial-nacional-ciudad-autonoma-buenos-aires-sapia-martin-francisco-otro-peugeot-citroen-argentina-sa-otro-ordinario-fa26130317-2026-03-17/123456789-713-0316-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', 'd37704f35aa303d6e1fac7e0ad801b16'),
('fallo', 'Palamara, Cosme y otro c/ Ferreria, Marcelo s/ Daños y perjuicios', null, 'Suprema Corte de Justicia de la Provincia de Buenos Aires', null, '2012-05-09'::date, null, 'PBA', 'Civil y Comercial', null, null, array['concurrencia']::text[], 'mixto', 'C. 108.063. Quien llega a la bocacalle por la izquierda debe reducir la velocidad y ceder el paso al que viene por la derecha, sin importar quién llegó primero; la regla es en principio absoluta, pero se valora junto con el resto de las normas de tránsito. Doctrina citada por las cámaras de PBA.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=85297', null, '2026-10-07'::date, 'relevamiento', 'cf7e525aa899e5248d95691345f7bc41'),
('doctrina', 'Accidentes de automotores privación de uso. Usuario no propietario', 'Carlos Alberto Echevesti', null, null, null, 1991, null, null, 'La Ley (resumen disponible en SAIJ Doctrina, DACJ910130)', null, array['privación de uso']::text[], null, 'Comenta un fallo que negó la privación de uso al usuario no titular y analiza el fundamento del rubro durante el tiempo de reparación. Útil cuando reclama quien usa el auto sin ser dueño.', false, 'https://www.saij.gob.ar/carlos-alberto-echevesti-accidentes-automotores-privacion-uso-usuario-propietario-dacj910130-1991-08-22/123456789-0abc-defg0310-19jcanirtcod', 'abierto', null, 'relevamiento', 'f413f0afcd166f1d934b2d0cb8132224'),
('doctrina', 'Daño emergente vs. lucro cesante', 'Diego López Olaciregui', null, null, null, 1995, null, null, 'La Ley (resumen disponible en SAIJ Doctrina, DACJ960237)', null, array['daño emergente']::text[], null, 'A partir de un caso de filtraciones en un consorcio, distingue el daño emergente del lucro cesante y sus exigencias de prueba. Sirve como base conceptual al delimitar rubros patrimoniales.', false, 'https://www.saij.gob.ar/diego-lopez-olaciregui-dano-emergente-vs-lucro-cesante-dacj960237-1995-11-07/123456789-0abc-defg7320-69jcanirtcod', 'abierto', null, 'relevamiento', '5a7cbd997a60aba703b743c7f8b93188'),
('doctrina', 'Daños y perjuicios derivados de la lesión a la integridad física de la persona', 'Roberto Antonio Vázquez Ferreyra', null, null, null, 1991, null, null, 'La Ley (resumen disponible en SAIJ Doctrina, DACJ910125)', null, array['incapacidad']::text[], null, 'Comenta una condena por colisión que reparó la incapacidad para las tareas habituales como daño patrimonial indirecto. Útil para fundar que la incapacidad abarca más que lo estrictamente laboral.', false, 'https://www.saij.gob.ar/roberto-antonio-vazquez-ferreyra-danos-perjuicios-derivados-lesion-integridad-fisica-persona-dacj910125-1991-08-09/123456789-0abc-defg5210-19jcanirtcod', 'abierto', null, 'relevamiento', '6321816dc9290f4d28120e07adc543c8'),
('doctrina', 'Incapacidad sobreviniente y lesión estética no son rubros resarcibles por sí mismos sino en cuanto causan daño patrimonial o moral', 'Jorge Bustamante Alsina', null, null, null, 1989, null, null, 'La Ley (resumen disponible en SAIJ Doctrina, DACJ970140)', null, array['incapacidad', 'daño moral']::text[], null, 'Sostiene, a partir de un caso de peatón embestido, que la incapacidad y la lesión estética se indemnizan por sus consecuencias patrimoniales o morales y no como rubros autónomos. Útil para encuadrar el reclamo y evitar superposiciones.', false, 'https://www.saij.gob.ar/jorge-bustamante-alsina-incapacidad-sobreviniente-lesion-estetica-son-rubros-resarcibles-si-mismos-sino-cuanto-causan-dano-patrimonial-moral-dacj970140-1989/123456789-0abc-defg0410-79jcanirtcod', 'abierto', null, 'relevamiento', '770e2af07716637d2938a0b93ee09bb7'),
('doctrina', 'Incapacidad temporaria. Merma transitoria de la vida extraproductiva', 'Hernán Daray', null, null, null, 1999, null, null, 'La Ley (resumen disponible en SAIJ Doctrina, DACA990125)', null, array['incapacidad']::text[], null, 'Propone indemnizar, además de la incapacidad permanente, la merma transitoria de la vida extraproductiva durante la convalecencia. Útil para reclamar el período de recuperación tras el accidente.', false, 'https://www.saij.gob.ar/hernan-daray-incapacidad-temporaria-merma-transitoria-vida-extraproductiva-daca990125-1999-04-21/123456789-0abc-defg5210-99acanirtcod', 'abierto', null, 'relevamiento', '45caa63e1a9ea715b137870fed0f991e'),
('doctrina', 'El daño moral en los Derechos Civil y Laboral', 'Roberto Antonio Vázquez Ferreyra', null, null, null, 1991, null, null, 'Jurisprudencia Argentina (resumen disponible en SAIJ Doctrina, DACA910132)', null, array['daño moral']::text[], null, 'Define el daño moral como lesión a un interés jurídico, con función resarcitoria y no punitiva, y repasa su procedencia y legitimación. Marco conceptual previo al art. 1741 CCyC.', false, 'https://www.saij.gob.ar/roberto-antonio-vazquez-ferreyra-dano-moral-derechos-civil-laboral-daca910132-1991-05-22/123456789-0abc-defg2310-19acanirtcod', 'abierto', null, 'relevamiento', 'fec457c47fb19a181ae420d90a47fa84'),
('doctrina', 'El peatón y su comportamiento vial: reglas a tener en cuenta para evaluar su conducta y eventual responsabilidad', 'Martín Diego Pirota', null, null, null, 2020, null, null, 'SAIJ Doctrina (DACF200095); también citado en Rubinzal Online, RC D 1009/2017', null, array['concurrencia']::text[], null, 'Sistematiza las prioridades y presunciones legales y pretorianas para atribuir responsabilidad en choques entre peatón y vehículo, en ruta o ciudad. Útil para discutir la culpa de la víctima.', false, 'https://www.saij.gob.ar/martin-diego-pirota-peaton-su-comportamiento-vial-reglas-tener-cuenta-para-evaluar-su-conducta-eventual-responsabilidad-dacf200095/123456789-0abc-defg5900-02fcanirtcod', 'abierto', null, 'relevamiento', 'aa2130e6b7991312bfac049696d6f782'),
('doctrina', 'La responsabilidad en accidentes viales - el automotor versus el peatón', 'Carlos Alberto Ghersi', null, null, null, 1995, null, null, 'Jurisprudencia Argentina (resumen disponible en SAIJ Doctrina, DACJ970107)', null, array['concurrencia']::text[], null, 'Comenta un fallo que rechazó la demanda de un ciclista por su propia imprudencia al cruzar la ruta. Muestra cómo se valora la conducta de la víctima como eximente.', false, 'https://www.saij.gob.ar/carlos-alberto-ghersi-responsabilidad-accidentes-viales-automotor-versus-peaton-dacj970107-1995-04/123456789-0abc-defg7010-79jcanirtcod', 'abierto', null, 'relevamiento', '9047388a1f167b38532a43a273e2f28f'),
('doctrina', 'La citación en garantía en el seguro de responsabilidad civil', 'Julio César Rivera', null, null, null, 1988, null, null, 'Jurisprudencia Argentina (resumen disponible en SAIJ Doctrina, DACN880076)', null, array['citación en garantía']::text[], null, 'Analiza la finalidad del seguro de responsabilidad civil, la falta de acción directa general y el alcance de la citación del asegurador. Base conceptual del art. 118.', false, 'https://www.saij.gob.ar/julio-cesar-rivera-citacion-garantia-seguro-responsabilidad-civil-dacn880076-1988/123456789-0abc-defg6700-88ncanirtcod', 'abierto', null, 'relevamiento', '5d6603df72956ee78f1167940637ea2b'),
('doctrina', 'El seguro de responsabilidad civil y la citación en garantía del asegurador. Su interpretación en la jurisprudencia de la provincia de Buenos Aires', 'Norberto Pantanali', null, null, null, 1996, null, null, 'La Ley (resumen disponible en SAIJ Doctrina, DACA960375)', null, array['citación en garantía']::text[], null, 'Describe la orientación restrictiva de la SCBA y de los tribunales provinciales sobre el alcance de la citación del art. 118. Útil para litigar en PBA.', false, 'https://www.saij.gob.ar/norberto-pantanali-seguro-responsabilidad-civil-citacion-garantia-asegurador-su-interpretacion-jurisprudencia-provincia-buenos-aires-daca960375-1996-10-18/123456789-0abc-defg5730-69acanirtcod', 'abierto', null, 'relevamiento', '3e266dfa0b90a14857898d55f841ba4e'),
('doctrina', 'Posición procesal del asegurador citado en garantía', 'Mario Alberto Fornaciari', null, null, null, 1993, null, null, 'SAIJ Doctrina (DACC930294)', null, array['citación en garantía']::text[], null, 'Estudia la posición del tercero citado en garantía en el proceso y el momento en que pasa a ser parte. Útil para planteos sobre defensas y facultades de la aseguradora.', false, 'https://www.saij.gob.ar/mario-alberto-fornaciari-posicion-procesal-asegurador-citado-garantia-dacc930294-1993/123456789-0abc-defg4920-39ccanirtcod', 'abierto', null, 'relevamiento', 'bd9bbf81e7015506f7dfcb20d9ca71cc'),
('doctrina', 'Citación en garantía, extensión al asegurador y a la víctima', 'Seminarios y Jornadas (conclusiones de congresos)', null, null, null, 1993, null, null, 'La Ley - Actualidad (resumen disponible en SAIJ Doctrina, DACC930329)', null, array['citación en garantía']::text[], null, 'Conclusiones que califican la citación pedida por el actor como demanda implícita contra la aseguradora, que asume calidad de parte. Respaldo doctrinal para extender la condena.', false, 'https://www.saij.gob.ar/seminarios-jornadas-conclusiones-congresos-citacion-garantia-extension-al-asegurador-victima-dacc930329-1993-08-12/123456789-0abc-defg9230-39ccanirtcod', 'abierto', null, 'relevamiento', '9d4f38779de5de2d6e2df2cd4a45f718'),
('doctrina', 'Liquidación de la aseguradora citada en garantía. Fuero de atracción y situación del damnificado', 'María Blanca Noodt Taquela', null, null, null, 1991, null, null, '2do. Congreso Internacional de Derecho de Daños (resumen disponible en SAIJ Doctrina, DACC960110)', null, array['citación en garantía']::text[], null, 'Analiza qué ocurre con el juicio de daños cuando la aseguradora citada entra en liquidación, y los efectos de desistir de su citación sobre el fuero de atracción. Útil ante aseguradoras liquidadas.', false, 'https://www.saij.gob.ar/maria-blanca-noodt-taquela-liquidacion-aseguradora-citada-garantia-fuero-atraccion-situacion-damnificado-dacc960110-1991-06-19/123456789-0abc-defg0110-69ccanirtcod', 'abierto', null, 'relevamiento', '9f11872df3aaf282f0e7125e8bbbb808'),
('doctrina', 'Regreso con gloria del fallo plenario ''Obarrio'' respecto a la inoponibilidad de la franquicia de acuerdo a la Resolución N° 39.927 de la S.S.N. (Julio de 2016)', 'Waldo Augusto Sobrino', null, null, null, 2017, null, null, 'SAIJ Doctrina (DACF170270)', null, array['franquicia']::text[], null, 'Critica la oponibilidad de la franquicia a víctimas del transporte público y sostiene que la Resolución SSN 39.927 de 2016 permite volver a la inoponibilidad. Argumento central para atacar franquicias.', false, 'https://www.saij.gob.ar/waldo-augusto-sobrino-regreso-gloria-fallo-plenario-obarrio-respecto-inoponibilidad-franquicia-acuerdo-resolucion-39927-ssn-julio-2016-dacf170270-2017-06-19/123456789-0abc-defg0720-71fcanirtcod', 'abierto', null, 'relevamiento', '4287fb65c47d62a92288eb96f15188b3'),
('doctrina', 'Efectos de la franquicia en el contrato de seguro sobre la responsabilidad civil', 'Seminarios y Jornadas (conclusiones de congresos)', null, null, null, 2007, null, null, 'SAIJ Doctrina (DACC070052)', null, array['franquicia']::text[], null, 'Conclusiones que admiten la oponibilidad de la franquicia al tercero ajeno al contrato, con salvedades cuando hay obligación legal de asegurar. Útil para conocer el punto de partida que hay que rebatir.', false, 'https://www.saij.gob.ar/seminarios-jornadas-conclusiones-congresos-efectos-franquicia-contrato-seguro-sobre-responsabilidad-civil-dacc070052-2007/123456789-0abc-defg2500-70ccanirtcod', 'abierto', null, 'relevamiento', '8668710e8137433c93ff99f04abc354d'),
('doctrina', 'Federalización del tema: tasa de los intereses', 'Augusto Mario Morello', null, null, null, 1993, null, null, 'El Derecho (resumen disponible en SAIJ Doctrina, DACJ930157)', null, array['intereses']::text[], null, 'Comenta una cámara federal que aplicó tasa activa apartándose del criterio de tasa pasiva de la CSJN. Antecedente histórico del debate sobre la tasa aplicable.', false, 'https://www.saij.gob.ar/augusto-mario-morello-federalizacion-tema-tasa-intereses-dacj930157-1993-03-05/123456789-0abc-defg7510-39jcanirtcod', 'abierto', null, 'relevamiento', '0e31d3ff8b645368368b7a9d608e53ac'),
('doctrina', 'Tasa de interés a aplicar sobre las deudas en mora', 'Mario Barbero Sarzabal', null, null, null, 1992, null, null, 'La Ley - Actualidad (resumen disponible en SAIJ Doctrina, DACJ920330)', null, array['intereses']::text[], null, 'Analiza la doctrina de la CSJN que fijó la tasa pasiva promedio para deudas en mora tras la convertibilidad. Contexto histórico para entender las posteriores doctrinas plenarias y de la SCBA.', false, 'https://www.saij.gob.ar/mario-barbero-sarzabal-tasa-interes-aplicar-sobre-deudas-mora-dacj920330-1992-06-18/123456789-0abc-defg0330-29jcanirtcod', 'abierto', null, 'relevamiento', 'b318d41d8c5aba7eaeaf47489976e13b'),
('doctrina', 'Incidencia de la mediación en los plazos de prescripción y caducidad', 'Abel Fleitas Ortiz de Rozas', null, null, null, 1997, null, null, 'El Derecho (resumen disponible en SAIJ Doctrina, DACA980083)', null, array['mediación', 'prescripción']::text[], null, 'Explica desde cuándo y hasta cuándo la mediación obligatoria suspende la prescripción (régimen de la Ley 24.573, hoy art. 18 de la Ley 26.589). Útil para calcular plazos al límite.', false, 'https://www.saij.gob.ar/abel-fleitas-ortiz-rozas-incidencia-mediacion-plazos-prescripcion-caducidad-daca980083-1997-11-28/123456789-0abc-defg3800-89acanirtcod', 'abierto', null, 'relevamiento', '366c408916884e0a4fd2e95131115b95'),
('doctrina', 'Incidencias de la ley de mediación en el Código Procesal Civil y Comercial de la Nación', 'Carlos Raúl Ponce', null, null, null, 1996, null, null, 'El Derecho (resumen disponible en SAIJ Doctrina, DACA960239)', null, array['mediación']::text[], null, 'Repasa cómo la mediación obligatoria modificó la forma de la demanda y otros institutos procesales en Nación. Referencia sobre los requisitos para demandar tras la mediación.', false, 'https://www.saij.gob.ar/carlos-raul-ponce-incidencias-ley-mediacion-codigo-procesal-civil-comercial-nacion-daca960239-1996-05-31/123456789-0abc-defg9320-69acanirtcod', 'abierto', null, 'relevamiento', '1d004a16d44e9c179d87eed44e4fea1b'),
('doctrina', 'Fórmulas y herramientas para cuantificar indemnizaciones por incapacidad en el nuevo Código', 'Hugo A. Acciarri', null, null, null, 2015, null, null, 'La Ley, 15/07/2015 (reproducido por la SCBA en su sitio sobre el CCyC)', null, array['incapacidad']::text[], null, 'Propone una fórmula flexible para el art. 1746 que admite ingresos variables, jubilación y tasa de descuento, con transparencia en el cálculo. Es la fórmula que aplica la CC0201 de La Plata.', false, 'https://www-2020.scba.gov.ar/leyorganica/ccyc30/pdfley/acciarri_formulas_y_herramientas_para_cuantificar_indemnizaciones_por_incapacidad.pdf', 'abierto', null, 'relevamiento', 'c997a2dcf372fabd4a6cc6d536f9992a'),
('doctrina', 'El deber de utilizar fórmulas matemáticas para fundar la indemnización de los daños por incapacidad sobreviniente', 'Jorge A. Filipini', null, null, null, 2015, null, null, 'Pensamiento Civil (revista digital)', null, array['incapacidad']::text[], null, 'Sostiene que el art. 1746 obliga a fundar la indemnización por incapacidad con un cálculo matemático explícito. Argumento para exigir fórmula en la sentencia.', false, 'https://pensamientocivil.com.ar/doctrina/1970-deber-utilizar-formulas-matematicas-para-fundar-indemnizacion-danos', 'abierto', null, 'relevamiento', '2fb4f5fe4464e8bb1c33e7a6486e4f8a')
